import {NextResponse} from "next/server"; import {getSession} from "@/lib/auth"; import {query} from "@/lib/db";
const admin=async()=>{const s=await getSession();return s?.role==="admin"?s:null};
export async function PATCH(req:Request,{params}:{params:Promise<{id:string}>}){if(!await admin())return NextResponse.json({error:"Admin access required"},{status:403});const{id}=await params;const b=await req.json();const title=String(b.title||"").trim();if(!title)return NextResponse.json({error:"Title required"},{status:400});const r=await query(`UPDATE tests SET title=$1,description=$2,duration_minutes=$3,total_marks=$4,is_published=$5 WHERE id=$6 RETURNING *`,[title,String(b.description||"").trim()||null,Number(b.durationMinutes||30),Number(b.totalMarks||0),Boolean(b.isPublished),id]);if(!r.rowCount)return NextResponse.json({error:"Test not found"},{status:404});return NextResponse.json({success:true,test:r.rows[0]})}
export async function DELETE(_:Request,{params}:{params:Promise<{id:string}>}){if(!await admin())return NextResponse.json({error:"Admin access required"},{status:403});const{id}=await params;const r=await query(`DELETE FROM tests WHERE id=$1`,[id]);if(!r.rowCount)return NextResponse.json({error:"Test not found"},{status:404});return NextResponse.json({success:true})}
